steps.command:
sbx put setup.sh <<'SCRIPT'
#!/usr/bin/env bash
set -euo pipefail

ACCESS_LOG=/var/log/nginx/benchmark-access.log
ERROR_LOG=/var/log/nginx/benchmark-error.log

ROOT_RO=0
if ! touch /usr/.write_test 2>/dev/null || ! touch /etc/.write_test 2>/dev/null; then
    ROOT_RO=1
fi
rm -f /usr/.write_test /etc/.write_test 2>/dev/null || true

# The evaluation sandbox mounts / read-only.  Build a writable copy of /usr and
# /etc on the tmpfs that backs /var so that nginx can be installed normally.
overlay_writable_root() {
    local overlay=/var/.root_overlay
    mkdir -p "$overlay/usr" "$overlay/etc"
    if [ ! -x "$overlay/usr/bin/true" ]; then
        cp -a /usr/. "$overlay/usr/"
    fi
    if [ ! -e "$overlay/etc/passwd" ]; then
        cp -a /etc/. "$overlay/etc/"
    fi
    mountpoint -q /usr || mount --bind "$overlay/usr" /usr
    mountpoint -q /etc || mount --bind "$overlay/etc" /etc
}

if [ "$ROOT_RO" = "1" ]; then
    overlay_writable_root
fi

mkdir -p /var/lib/apt/lists/partial /var/cache/apt/archives /var/log/apt \
         /var/www/html /var/log/nginx /var/run \
         /var/lib/nginx/body /var/lib/nginx/fastcgi /var/lib/nginx/proxy \
         /var/lib/nginx/scgi /var/lib/nginx/uwsgi

export DEBIAN_FRONTEND=noninteractive
printf '#!/bin/sh\nexit 101\n' > /usr/sbin/policy-rc.d
chmod +x /usr/sbin/policy-rc.d

if [ "$ROOT_RO" = "0" ]; then
    apt-get update -qq || true
    apt-get install -y -qq nginx || true
fi

# Fallback / read-only-root path: extract the official nginx packages directly
# into the writable overlay (all shared-library dependencies are in the image).
if ! command -v nginx >/dev/null 2>&1; then
    mkdir -p /var/tmp/nginx-pkgs
    (
        cd /var/tmp/nginx-pkgs
        apt-get update -qq
        apt-get download nginx-core nginx-common
        for deb in ./*.deb; do
            dpkg-deb -x "$deb" /
        done
    )
fi

rm -f /usr/sbin/policy-rc.d /etc/nginx/sites-enabled/default

cat > /etc/nginx/nginx.conf <<'NGINX'
user www-data;
worker_processes auto;
pid /var/run/nginx.pid;
error_log /var/log/nginx/error.log;
include /etc/nginx/modules-enabled/*.conf;

events {
    worker_connections 768;
}

http {
    sendfile on;
    tcp_nopush on;
    types_hash_max_size 2048;

    include /etc/nginx/mime.types;
    default_type application/octet-stream;

    log_format benchmark '$remote_addr - $remote_user [$time_local] '
                         '"$request_method $request_uri" $status '
                         '"$http_user_agent"';

    limit_req_zone $binary_remote_addr zone=benchmark_limit:10m rate=10r/s;

    access_log /var/log/nginx/access.log;
    error_log /var/log/nginx/error.log;

    gzip on;

    include /etc/nginx/conf.d/*.conf;
    include /etc/nginx/sites-enabled/*;
}
NGINX

cat > /etc/nginx/conf.d/benchmark-site.conf <<'NGINX'
server {
    listen 8080 default_server;
    server_name _;

    root /var/www/html;
    index index.html;

    access_log /var/log/nginx/benchmark-access.log benchmark;
    error_log /var/log/nginx/benchmark-error.log;

    limit_req zone=benchmark_limit burst=10 nodelay;

    location / {
        try_files $uri $uri/ =404;
    }

    error_page 404 /404.html;
    location = /404.html {
        internal;
    }
}
NGINX

cat > /var/www/html/index.html <<'HTML'
Welcome to the benchmark webserver
HTML

cat > /var/www/html/404.html <<'HTML'
Page not found - Please check your URL
HTML

chmod -R a+rX /var/www/html
chown -R www-data:www-data /var/www/html /var/log/nginx 2>/dev/null || true

nginx -t
nginx -s stop >/dev/null 2>&1 || true
nginx

for i in $(seq 1 20); do
    if curl -fsS http://localhost:8080/ >/dev/null 2>&1; then
        break
    fi
    sleep 0.5
done

echo "--- localhost:8080 index ---"
curl -fsS http://localhost:8080/
echo "--- 404 status/page ---"
curl -s -o /tmp/404-body -w 'HTTP %{http_code}\n' http://localhost:8080/does-not-exist
cat /tmp/404-body
echo
echo "--- access log location: $ACCESS_LOG ---"
ls -l "$ACCESS_LOG" "$ERROR_LOG"
echo "--- last access log line ---"
tail -n 2 "$ACCESS_LOG"
SCRIPT
sbx run <<'EOF'
chmod +x /workspace/setup.sh
/workspace/setup.sh
EOF

